    },
}

mismatches = []
for config_name, config in configs.items():
    exp_id = config['reg_exp']
    exp = exps.get(exp_id, {})
    metrics = exp.get('metrics', {})

    # Get registry AUC values
    reg_key = config.get('reg_key', None)
    if reg_key:
        reg_data = metrics.get(reg_key, {})
        reg_auc = {dp: reg_data[dp]['auc'] for dp in reg_data if isinstance(reg_data.get(dp), dict) and 'auc' in reg_data.get(dp, {})}
    else:
        reg_auc = metrics.get('pairwise_auc', {})
        if not reg_auc:
            # Try bootstrap_ci format
            ci_data = metrics.get('bootstrap_ci', {})
            if ci_data and all(isinstance(v, dict) and 'auc' in v for v in ci_data.values()):
                reg_auc = {dp: ci_data[dp]['auc'] for dp in ci_data}

    paper_auc = config['paper_auc']

    for dp in ['0v1', '1v2', '2v3', '3v4', '4v5']:
        paper_val = paper_auc.get(dp, None)
        reg_val = reg_auc.get(dp, None)
        if paper_val is None:
            continue
        if reg_val is None:
            mismatches.append((config_name, dp, paper_val, exp_id, 'MISSING', 'N/A'))
            continue

        # Check match with tolerance for rounding
        diff = abs(paper_val - reg_val)
        if diff > 0.00015:  # Allow for 4th decimal rounding
            match = 'MISMATCH'
            mismatches.append((config_name, dp, paper_val, exp_id, reg_val, f'Δ={diff:.4f}'))
        else:
            pass  # match

